@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_player_skin_is_packet_93(version):
    assert version.PACKETS[93] is version.PlayerSkinPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_skin_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_player_skin_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_1001_body_is_the_2168_one_less_the_profile_hash():
    assert bytes(PERSONA_1001) == V2168_PERSONA[:-13] + V2168_PERSONA[-8:]


def test_a_1001_body_round_trips():
    assert v1001.PlayerSkinPacket.from_bytes(bytes(PERSONA_1001)) == PERSONA_1001


def test_a_2168_body_does_not_decode_as_a_1001_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v1001.PlayerSkinPacket.from_bytes(V2168_PERSONA)


def test_a_1001_body_does_not_decode_as_a_2168_one():
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlayerSkinPacket.from_bytes(bytes(PERSONA_1001))


def test_the_pre_944_body_is_not_the_1001_one():
    assert v924.PlayerSkinPacket is not v1001.PlayerSkinPacket


@pytest.fixture
def minimal_2225():
    return v2225.PlayerSkinPacket(
        uuid=PLAYER,
        skin=v2225.SerializedSkinRef(
            id="sid",
            resource_patch="patch",
            trusted_skin_flag=v2225.TrustedSkinFlag.FALSE,
            profile_hash="hash",
        ),
        localized_new_skin_name="new",
        localized_old_skin_name="old",
    )


def test_2225_drops_the_play_fab_id_from_the_skin(minimal_2225):
    assert bytes(minimal_2225) == V2168_MINIMAL[:20] + V2168_MINIMAL[25:]


def test_a_2225_skin_round_trips(minimal_2225):
    assert v2225.PlayerSkinPacket.from_bytes(bytes(minimal_2225)) == minimal_2225


@pytest.mark.parametrize(
    ("member", "value"),
    [
        pytest.param(v2168.PieceType.UNSUPPORTED, 28, id="v2168-unsupported"),
        pytest.param(v2168.PieceType.COUNT, 29, id="v2168-count"),
        pytest.param(v2225.PieceType.COCO, 28, id="v2225-coco"),
        pytest.param(v2225.PieceType.UNSUPPORTED, 29, id="v2225-unsupported"),
        pytest.param(v2225.PieceType.COUNT, 30, id="v2225-count"),
    ],
)
def test_2225_inserts_coco_into_the_persona_piece_types(member, value):
    assert member == value
